44	interface Evento {
45	  id: string;
46	  nome: string;
47	  data_inicio: string;
48	  hora_inicio: string | null;
49	  endereco: string | null;
50	  status:
51	    | 'planejamento'
52	    | 'confirmado'
53	    | 'concluido'
54	    | 'cancelado'
55	    | 'aberto'
56	    | 'finalizado';
