73	export default function EventDashboard() {
74	  const { id } = useParams<{ id: string }>();
75	  const navigate = useNavigate();
76	  const isMobile = useIsMobile();
77	  const telemetryAttrs = useTelemetryAttrs();
78	  const [evento, setEvento] = useState<Evento | null>(null);
79	  const [loading, setLoading] = useState(true);
80	  const [activeTab, setActiveTab] = useState('overview');
81	  const [metricas, setMetricas] = useState<MetricaEvento | null>(null);
82	  const {
83	    logs,
84	    loading: loadingLogs,
85	    addLog,
86	    fetchLogs,
87	  } = useChangelog(id || '', 'EVENTO');
88	
89	  useEffect(() => {
90	    if (id) {
91	      fetchEvento(id);
92	      fetchMetricas(id);
93	    }
94	    // eslint-disable-next-line react-hooks/exhaustive-deps
95	  }, [id]);
96	
97	  const fetchEvento = async (eventId: string) => {
98	    setLoading(true);
99	    try {
100	      await withTrace('gerencia.evento_dashboard.carregar', async () => {
101	        const startTime = performance.now();
102	        const { data, error } = await supabase
103	          .from('eventos')
104	          .select('*')
105	          .eq('id', eventId)
106	          .single();
107	
108	        if (error) throw error;
